Map<int, String>? _map;

Map<int, String> _table() {
  if (_map != null) return _map!;
  final m = <int, String>{};
  for (final entry in _encoded.split('|')) {
    final parts = entry.split(',');
    final cp = int.parse(parts[0], radix: 16);
    final base = parts[1]
        .split('.')
        .map((h) => int.parse(h, radix: 16))
        .toList();
    m[cp] = String.fromCharCodes(base);
  }
  return _map = m;
}

/// يردّ أشكالَ العرض إلى الحروف الأساسيّة، ويُسقط التشكيل، ويوحّد
/// الألفَ بأشكالها.
///
/// فيصير نصُّ الورقة قابلاً للمقارنة بالعربيّ كما يُكتب في الاختبار.
///
/// ⚠️ **وتوحيدُ الألف لازمٌ لا تجميل**: تفكيكُ NFKD يُخرج الهمزةَ
/// علامةً مركّبةً منفصلة (ا + U+0655)، بينما تُكتب في المصدر حرفاً
/// واحداً مركّباً (إ = U+0625). فبلا التوحيد لا تتطابق «إيصالاً»
/// المطبوعةُ مع «إيصالاً» المكتوبة — وهي مقيسةٌ لا مفترَضة.
String deshapeArabic(String s) {
  final t = _table();
  final b = StringBuffer();
  for (final r in s.runes) {
    // تشكيلٌ (فتحة/ضمّة/شدّة/تنوين) وهمزةٌ مركّبةٌ — تُسقط،
    // فالمقارنةُ على هيكل الحروف.
    if (r >= 0x064B && r <= 0x0655) continue;
    final mapped = t[r] ?? String.fromCharCode(r);
    for (final c in mapped.runes) {
      // آ أ إ ← ا
      if (c == 0x0622 || c == 0x0623 || c == 0x0625) {
        b.write(String.fromCharCode(0x0627));
      } else if (c >= 0x064B && c <= 0x0655) {
        continue;
      } else {
        b.write(String.fromCharCode(c));
      }
    }
  }
  return b.toString();
}
